import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const DEFAULT_OUT_FILE = resolve(SCRIPT_DIR, '..', 'seed-output', 'exercise-catalog-import.sql');

const CLI_HELP_TEXT = `
Usage:
  pnpm run import:exercise-catalog -- --file=PATH [--out=PATH] [--replace]

Options:
  --file     Seed JSON generated by pnpm run seed:exercise-catalog.
  --out      SQL output path. Defaults to ./seed-output/exercise-catalog-import.sql.
  --replace  Delete existing catalog rows before inserting the seed data.
`;

const args = parseCliArgs(process.argv.slice(2));

function parseCliArgs(argv) {
  const parsed = Object.fromEntries(
    argv
      .filter((arg) => arg.startsWith('--'))
      .map((arg) => arg.replace(/^--/, ''))
      .map((arg) => {
        const splitAt = arg.indexOf('=');
        if (splitAt === -1) {
          return [arg, 'true'];
        }
        return [arg.slice(0, splitAt), arg.slice(splitAt + 1)];
      }),
  );

  if (argv.includes('-h')) {
    parsed.help = 'true';
  }

  return parsed;
}

export async function runImportScript(cliArgs = args) {
  if (Object.prototype.hasOwnProperty.call(cliArgs, 'help')) {
    console.log(CLI_HELP_TEXT);
    return null;
  }

  if (!cliArgs.file) {
    throw new Error('Missing required --file=PATH option.');
  }

  const inputFile = resolve(SCRIPT_DIR, cliArgs.file);
  const outFile = cliArgs.out ? resolve(SCRIPT_DIR, cliArgs.out) : DEFAULT_OUT_FILE;
  const seed = JSON.parse(await readFile(inputFile, 'utf8'));
  const sql = buildCatalogImportSql(seed, {
    replace: Object.prototype.hasOwnProperty.call(cliArgs, 'replace'),
  });

  await mkdir(dirname(outFile), { recursive: true });
  await writeFile(outFile, `${sql}\n`, 'utf8');

  console.log(`Wrote catalog import SQL to ${outFile}`);
  console.log(
    `Import summary: ${seed.exercises?.length ?? 0} exercises, ${seed.muscles?.length ?? 0} muscles, ${
      seed.equipment?.length ?? 0
    } equipment records, ${seed.media?.length ?? 0} media records`,
  );
  return { outFile, sql };
}

export function buildCatalogImportSql(seed, options = {}) {
  const generatedAt = readText(seed.generatedAt) || new Date().toISOString();
  const lines = [];

  if (options.replace) {
    lines.push(
      'DELETE FROM exercise_aliases;',
      'DELETE FROM exercise_media;',
      'DELETE FROM exercise_equipment;',
      'DELETE FROM exercise_muscles;',
      'DELETE FROM master_exercises;',
      'DELETE FROM master_equipment;',
      'DELETE FROM master_muscles;',
    );
  }

  for (const muscle of seed.muscles ?? []) {
    lines.push(
      insertOrReplace('master_muscles', {
        id: muscle.id,
        canonical_id: muscle.canonicalId,
        name: muscle.name,
        name_localized: muscle.nameLocalized,
        ...sourceFields(muscle),
        created_at: generatedAt,
        updated_at: generatedAt,
      }),
    );
  }

  for (const equipment of seed.equipment ?? []) {
    lines.push(
      insertOrReplace('master_equipment', {
        id: equipment.id,
        canonical_id: equipment.canonicalId,
        name: equipment.name,
        name_localized: equipment.nameLocalized,
        ...sourceFields(equipment),
        created_at: generatedAt,
        updated_at: generatedAt,
      }),
    );
  }

  for (const exercise of seed.exercises ?? []) {
    lines.push(
      insertOrReplace('master_exercises', {
        id: exercise.id,
        canonical_id: exercise.canonicalId,
        name: exercise.name,
        name_localized: exercise.nameLocalized,
        movement_pattern: exercise.movementPattern,
        instructions: exercise.instructions,
        recommended_level: exercise.recommendedLevel,
        goal_tags_json: JSON.stringify(exercise.goalTags ?? []),
        excluded_limitations_json: JSON.stringify(exercise.excludedLimitations ?? []),
        ...sourceFields(exercise),
        created_at: generatedAt,
        updated_at: generatedAt,
      }),
    );

    for (const alias of exercise.aliases ?? []) {
      lines.push(
        insertOrReplace('exercise_aliases', {
          id: `alias_${exercise.id}_${hashText(alias)}`,
          exercise_id: exercise.id,
          alias,
          locale: 'en',
          ...sourceFields(exercise),
          source_id: `${exercise.sourceId}:alias:${hashText(alias)}`,
          created_at: generatedAt,
          updated_at: generatedAt,
        }),
      );
    }
  }

  for (const link of seed.exerciseMuscles ?? []) {
    lines.push(
      insertOrReplace('exercise_muscles', {
        exercise_id: link.exerciseId,
        muscle_id: link.muscleId,
        is_primary: link.isPrimary ? 1 : 0,
      }),
    );
  }

  for (const link of seed.exerciseEquipment ?? []) {
    lines.push(
      insertOrReplace('exercise_equipment', {
        exercise_id: link.exerciseId,
        equipment_id: link.equipmentId,
      }),
    );
  }

  for (const media of seed.media ?? []) {
    lines.push(
      insertOrReplace('exercise_media', {
        id: media.id,
        exercise_id: media.exerciseId,
        storage_url: media.storageUrl,
        media_type: media.mediaType,
        width_px: media.widthPx,
        height_px: media.heightPx,
        alt_text: media.altText,
        ...sourceFields(media),
        created_at: generatedAt,
        updated_at: generatedAt,
      }),
    );
  }

  return lines.join('\n');
}

function sourceFields(record) {
  return {
    source: record.source,
    source_id: record.sourceId,
    license_name: record.licenseName,
    license_url: record.licenseUrl,
    license_author: record.licenseAuthor,
    attribution_text: record.attributionText,
  };
}

function insertOrReplace(table, values) {
  const columns = Object.keys(values);
  const renderedValues = columns.map((column) => sqlValue(values[column]));
  return `INSERT OR REPLACE INTO ${table} (${columns.join(', ')}) VALUES (${renderedValues.join(', ')});`;
}

function sqlValue(value) {
  if (value === undefined || value === null || value === '') {
    return 'NULL';
  }
  if (typeof value === 'number') {
    return Number.isFinite(value) ? String(value) : 'NULL';
  }
  return `'${String(value).replaceAll("'", "''")}'`;
}

function hashText(value) {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return Math.abs(hash >>> 0).toString(16);
}

function readText(value) {
  return typeof value === 'string' ? value.trim() : '';
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  runImportScript().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
